--- index.html
+++ index.html
@@ -146,9 +146,9 @@
 renderer.domElement.addEventListener('pointermove',e=>{pointer.x=e.clientX/innerWidth*2-1;pointer.y=-(e.clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(interactables.map(x=>x.mesh),false);renderer.domElement.style.cursor=hits.length?'pointer':'default'});
 renderer.domElement.addEventListener('click',e=>{pointer.x=e.clientX/innerWidth*2-1;pointer.y=-(e.clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(interactables.map(x=>x.mesh),false);if(hits.length){const target=interactables.find(x=>x.mesh===hits[0].object);if(target)doTask(target.id)}});
 function resize(){const w=sceneHost.clientWidth,h=sceneHost.clientHeight,aspect=w/h;const view=9.4;camera.left=-view*aspect;camera.right=view*aspect;camera.top=view;camera.bottom=-view;camera.updateProjectionMatrix();renderer.setSize(w,h,false)}window.addEventListener('resize',resize);resize();
 const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();if(avatar.userData.dest){const d=avatar.userData.dest;const dx=d.x-avatar.position.x,dz=d.z-avatar.position.z;const len=Math.hypot(dx,dz);if(len>.08){avatar.position.x+=dx/len*.075;avatar.position.z+=dz/len*.075;avatar.rotation.y=Math.atan2(dx,dz);avatar.position.y=Math.abs(Math.sin(t*12))*.055}else{avatar.userData.dest=null;avatar.position.y=0}}
-baby.position.y=1+Math.sin(t*2.7)*.035+baby.userData.fed*.02;baby.rotation.z=Math.sin(t*1.6)*.025;
+baby.position.y=1+Math.sin(t*2.7)*.035+(baby.userData.fed?.02:0);baby.rotation.z=Math.sin(t*1.6)*.025;
 if(!complete){renderer.render(scene,camera)}else renderer.render(scene,camera)}animate();
 </script>
 </body>
 </html>
